package crypto

import (
	"bytes"
	"crypto/aes"
	"encoding/hex"
	"testing"
)

func TestIGEEncryptDecryptVectors(t *testing.T) {
	key := mustHex("E68CA5ABA101FFCA0ADDA66303A57AFFAA2712FB16A7B8DAFC72C25E8A73A368")
	iv := mustHex("0A355D4431B9DDD91A51EFF3F7D340D64F0390C53F91DC53C331D43C264F835B")
	plaintext := mustHex("")
	ciphertext := mustHex("")

	block, err := aes.NewCipher(key)
	if err != nil {
		t.Fatalf("new cipher: %v", err)
	}

	encrypted := make([]byte, len(plaintext))
	EncryptIGE(encrypted, plaintext, block, iv)
	if !bytes.Equal(encrypted, ciphertext) {
		t.Fatalf("encrypted output mismatch")
	}

	decrypted := make([]byte, len(ciphertext))
	DecryptIGE(decrypted, ciphertext, block, iv)
	if !bytes.Equal(decrypted, plaintext) {
		t.Fatalf("decrypted output mismatch")
	}

	mode := NewAESIGE(key, iv)
	encryptedMode := make([]byte, len(plaintext))
	mode.CryptBlocks(encryptedMode, plaintext)
	if !bytes.Equal(encryptedMode, ciphertext) {
		t.Fatalf("block mode output mismatch")
	}

	decryptMode := NewAESIGEDecrypt(key, iv)
	decryptedMode := make([]byte, len(ciphertext))
	decryptMode.CryptBlocks(decryptedMode, ciphertext)
	if !bytes.Equal(decryptedMode, plaintext) {
		t.Fatalf("block mode decrypt output mismatch")
	}
}

func mustHex(s string) []byte {
	data, err := hex.DecodeString(s)
	if err != nil {
		panic(err)
	}
	return data
}
